  "Descuentos y combos": "Discounts and bundles",
  "Planes de socios": "Membership plans",
  "Cada plan es una actividad o un pase, con un precio para cada duración: por mes, por dos o tres meses, por año o lo que quieras. La cuota se genera sola al empezar cada período y vence ese mismo día.": "Each plan is an activity or a pass, with a price for each duration: monthly, every two or three months, yearly or whatever you want. The fee is created automatically at the start of each period and is due that same day.",
  "Plan": "Plan",
  "Duraciones y precios": "Durations and prices",
  "Nuevo plan": "New plan",
  "Nombre del plan": "Plan name",
  "Pase libre, Musculación 3 veces, Funcional…": "Unlimited pass, Weights 3 times a week, Functional…",
  "Cada duración tiene su precio: de 1 a 36 meses. Por ejemplo, mensual a $30.000 y trimestral a $80.000.": "Each duration has its price: from 1 to 36 months. For example, monthly at $30,000 and quarterly at $80,000.",
  "Agregar otra duración": "Add another duration",
  "Un precio nuevo rige desde la próxima cuota de cada socio. Una duración que sacás deja de ofrecerse, pero quien la tiene la sigue pagando.": "A new price applies from each member's next fee. A duration you remove stops being offered, but whoever has it keeps paying it.",
  "Cancelar": "Cancel",
  "Agregar plan": "Add plan",
  "Bajan solos el precio de las cuotas: cuando un socio combina ciertos planes, cuando hace varios, o el que le elijas a mano (familiar, estudiante). Si le tocan dos, se aplica el mayor.": "They lower fee prices automatically: when a member combines certain plans, when they take several, or the one you choose manually (family, student). If two apply, the larger one is used.",
