  "(display-mode: standalone)": null,
  "Ya está instalada en este dispositivo: se abre desde su ícono, como cualquier app.": "It's already installed on this device: it opens from its icon, like any app.",
  "Instalala para abrirla desde un ícono, a pantalla completa, y ver lo último que cargaste aunque no haya conexión.": "Install it to open it from an icon, full screen, and see the latest data you loaded even without a connection.",
  "En el iPhone o el iPad, abrí Nexo en Safari, tocá Compartir y después “Agregar a inicio”.": "On iPhone or iPad, open Nexo in Safari, tap Share and then “Add to Home Screen”.",
  "Para instalarla, Nexo tiene que abrirse desde una dirección segura (https).": "To install it, Nexo has to be opened from a secure address (https).",
  "Para instalarla, abrí Nexo en Chrome o Edge, en el celular o en la compu, y elegí “Instalar” en el menú del navegador.": "To install it, open Nexo in Chrome or Edge, on your phone or computer, and choose “Install” in the browser menu.",
  "Nexo quedó instalada. La vas a encontrar con su ícono.": "Nexo was installed. You'll find it with its icon.",

