  // frontend/js/dominios/factura-electronica.js
  "Factura Electrónica - Monotributo - Web Services": null,
  "Nexo está en el ambiente de prueba de ARCA: los CAE son de prueba y cada comprobante sale con la leyenda “Comprobante de prueba – sin validez fiscal”.": "Nexo is in ARCA's test environment: CAEs are test ones and every receipt carries the legend “Test receipt – no tax validity”.",
  "ARCA simulado: los CAE los inventa Nexo, para probar sin conexión. Nada de esto llega a ARCA.": "Simulated ARCA: CAEs are made up by Nexo, to test without a connection. None of this reaches ARCA.",
  "Este servidor todavía no tiene el certificado de Nexo para hablar con ARCA. Avisale a quien administra Nexo.": "This server doesn't have Nexo's certificate to talk to ARCA yet. Let whoever runs Nexo know.",
  "Punto de venta {0} · verificada el {1}. Cada factura y nota de crédito sale con CAE.": "Point of sale {0} · verified on {1}. Every invoice and credit note comes with a CAE.",
  "Apagar": "Turn off",
  "Todavía no está activa: seguí los pasos de abajo. Hasta entonces, tus comprobantes siguen siendo internos.": "It's not active yet: follow the steps below. Until then, your receipts stay internal.",
  "CUIT {0}. Con tu condición frente al IVA, Nexo elige solo la letra de cada comprobante.": "CUIT {0}. With your VAT status, Nexo picks the letter of each receipt automatically.",
  "Nexo necesita el CUIT del negocio y su condición frente al IVA: con eso arma cada comprobante.": "Nexo needs the business CUIT and its VAT status: with that it builds each receipt.",
  "(se informa al pasar a producción)": "(reported when moving to production)",
  "No uses los puntos {0}: ya tienen comprobantes internos de Nexo.": "Don't use points {0}: they already have internal Nexo receipts.",
  "No uses el punto {0}: ya tiene comprobantes internos de Nexo.": "Don't use point {0}: it already has internal Nexo receipts.",
  "En el ambiente de prueba no hace falta crearlo en ARCA: sirve cualquier número.": "In the test environment you don't need to create it in ARCA: any number works.",
  "Verificar de nuevo": "Verify again",
  "Ya está verificada.": "It's already verified.",
  "Activa, con CAE de ARCA": "Active, with ARCA CAE",
  "No se pudo cargar la factura electrónica.": "Electronic invoicing couldn't be loaded.",
  "El punto de venta es un número entre 1 y 99998.": "The point of sale is a number between 1 and 99998.",
  "No se pudo guardar el punto de venta.": "The point of sale couldn't be saved.",
  "Punto de venta guardado. Ahora verificalo con ARCA.": "Point of sale saved. Now verify it with ARCA.",
  "Consultando a ARCA…": "Checking with ARCA…",
  "ARCA no respondió. Probá de nuevo en unos minutos.": "ARCA didn't respond. Try again in a few minutes.",
  "Listo: la factura electrónica está activa. Tu próxima factura sale con CAE.": "Done: electronic invoicing is active. Your next invoice comes with a CAE.",
  "Apagar la factura electrónica": "Turn off electronic invoicing",
  "Tus próximos comprobantes vuelven a ser internos, sin CAE. Lo que ya está autorizado no cambia, y la podés volver a prender verificando de nuevo.": "Your next receipts go back to being internal, without a CAE. What's already authorized doesn't change, and you can turn it back on by verifying again.",
  "No se pudo apagar la factura electrónica.": "Electronic invoicing couldn't be turned off.",
  "La factura electrónica quedó apagada.": "Electronic invoicing was turned off.",

