  "Nexo deja de actualizar el stock y el precio de tus publicaciones y de traer sus ventas. Las publicaciones siguen en Mercado Libre, y las ventas que ya llegaron quedan en Nexo. Para sacarle el permiso a Nexo del todo, hacelo también desde tu cuenta de Mercado Libre.": "Nexo stops updating the stock and price of your listings and bringing in their sales. The listings stay on Mercado Libre, and the sales that already arrived stay in Nexo. To remove Nexo's permission completely, also do it from your Mercado Libre account.",
