  "WhatsApp desvinculado.": "WhatsApp unlinked.",

  // frontend/js/sesion.js
  "Cambiaste de negocio en otra pestaña. Esta se actualizó para mostrar en el que estás.": "You switched business in another tab. This one was updated to show the one you're in.",
  "lo último que se cargó": "the latest data loaded",
  "lo que se cargó a las {0}": "the data loaded at {0}",
  "lo que se cargó el {0} a las {1}": "the data loaded on {0} at {1}",
  "No se pudo abrir el alta de cuenta. Recargá la página.": "The account setup couldn't be opened. Reload the page.",
  "Estás probando Nexo con {0}, un negocio de ejemplo. Cargá lo que quieras: es tuyo, no lo ve nadie más y se borra solo el {1}.": "You're trying Nexo with {0}, a sample business. Enter whatever you want: it's yours, nobody else sees it and it's deleted automatically on {1}.",
  "En esta instalación de Nexo no se puede probar sin una cuenta.": "On this Nexo installation you can't try it without an account.",
  "Cada visitante tiene el suyo: lo que cargues no lo ve nadie más, y se borra solo en {0} días.": "Each visitor gets their own: what you enter nobody else sees, and it's deleted automatically in {0} days.",
  "Abriendo {0}…": "Opening {0}…",
  "Armando {0}: tarda unos segundos…": "Setting up {0}: it takes a few seconds…",
  "No se pudo abrir el negocio de ejemplo.": "The sample business couldn't be opened.",
  "No se pudo cargar la aplicación. Recargá la página.": "The app couldn't be loaded. Reload the page.",
  "English": null,
  "Español": null,
  "No se pudo iniciar sesión.": "Couldn't sign in.",
  "No se pudo conectar con el servidor.": "Couldn't connect to the server.",
  "Sin conexión. Para usar Nexo sin conexión, primero entrá una vez con conexión desde este dispositivo.": "No connection. To use Nexo offline, first sign in once with a connection from this device.",
  "Listo: tu mail {0} quedó confirmado.": "Done: your email {0} is confirmed.",
  "Cambiaron los términos": "The terms changed",
  "Actualizamos los términos o la política de privacidad de Nexo. Leelos y aceptalos para seguir usando Nexo.": "We updated Nexo's terms or privacy policy. Read and accept them to keep using Nexo.",
  "No se pudo cargar la página. Recargá para probar de nuevo.": "The page couldn't be loaded. Reload to try again.",
  "No se pudo guardar. Probá de nuevo.": "It couldn't be saved. Try again.",
  "error:No se pudo aceptar la invitación. Probá de nuevo desde el enlace del mail.": "error:The invitation couldn't be accepted. Try again from the email link.",
  "Ir a Nexo": "Go to Nexo",
  "Este enlace no sirve": "This link doesn't work",
  "Puede que esté incompleto o que ya te hayan mandado uno más nuevo. Pedile a quien te invitó que te lo mande de nuevo.": "It may be incomplete or you may have been sent a newer one. Ask whoever invited you to send it again.",
  "{0} te invitó a {1}": "{0} invited you to {1}",
  "La invitación venció. Pedile a {0} que te la mande de nuevo desde Nexo.": "The invitation expired. Ask {0} to send it again from Nexo.",
  "{0} canceló esta invitación.": "{0} canceled this invitation.",
  "Ya la aceptaste. Entrá con tu mail para trabajar en {0}.": "You already accepted it. Sign in with your email to work in {0}.",
  "La rechazaste. Si cambiaste de idea, pedile a {0} que te invite de nuevo.": "You declined it. If you changed your mind, ask {0} to invite you again.",
  "Te suma a su equipo como {0}.": "They're adding you to their team as {0}.",
  "Te suma a su equipo como {0}. Tus otros negocios siguen igual: pasás de uno a otro desde arriba del menú.": "They're adding you to their team as {0}. Your other businesses stay the same: you switch between them from the top of the menu.",
  "Te suma a su equipo como {0}. Ya tenés cuenta con {1}: ingresá y la invitación se acepta sola.": "They're adding you to their team as {0}. You already have an account with {1}: sign in and the invitation is accepted automatically.",
  "Te suma a su equipo como {0}. Creá tu cuenta para entrar: con ella vas a ingresar a Nexo.": "They're adding you to their team as {0}. Create your account to get in: you'll sign in to Nexo with it.",
  "Cerrar sesión y entrar con ese mail": "Sign out and sign in with that email",
  "No se pudo crear la cuenta.": "The account couldn't be created.",
  "Listo: ya estás en el equipo. Te damos la bienvenida a Nexo.": "Done: you're on the team now. Welcome to Nexo.",
  "Te invitó {0}, como {1}": "{0} invited you, as {1}",
  "Te invitaron a estos negocios. Aceptá para empezar a trabajar, o creá el tuyo.": "You were invited to these businesses. Accept to start working, or create your own.",
  "Cuando alguien te invite, la invitación aparece acá una vez que confirmes tu mail: te mandamos un enlace a {0}. Si tenés tu propio negocio, crealo.": "When someone invites you, the invitation shows up here once you confirm your email: we sent a link to {0}. If you have your own business, create it.",
  "No se pudo responder la invitación.": "The invitation couldn't be answered.",
  "Si hay una cuenta de Nexo con {0}, te llega un mail con un enlace para elegir una contraseña nueva.": "If there's a Nexo account with {0}, you'll get an email with a link to choose a new password.",
  "Vence en 30 minutos. Si no lo ves en unos minutos, buscalo en el spam.": "It expires in 30 minutes. If you don't see it in a few minutes, check your spam.",
  "Este enlace ya no sirve": "This link no longer works",
  "Venció (dura 30 minutos), ya se usó o pediste uno más nuevo. Pedí otro y usá el último que te llegue.": "It expired (it lasts 30 minutes), was already used or you requested a newer one. Request another one and use the last one you receive.",
  "No se pudo guardar la contraseña.": "The password couldn't be saved.",
  "Listo: tu contraseña cambió. Entrá con la nueva.": "Done: your password changed. Sign in with the new one.",
  "{0} se está dando de baja": "{0} is being closed",
  "Nadie del equipo lo puede usar. El {0} se borra todo lo que tiene. Si te arrepentiste, cancelá la baja y sigue todo como estaba.": "Nobody on the team can use it. On {0} everything it has is deleted. If you changed your mind, cancel the closing and everything stays as it was.",
  "Quien lo administra pidió darlo de baja, así que nadie lo puede usar. El {0} se borran sus datos. Si es un error, avisale para que la cancele.": "Whoever runs it asked to close it, so nobody can use it. On {0} its data is deleted. If it's a mistake, let them know so they cancel it.",
  "Entrar": "Go in",
  "No se pudo entrar a ese negocio. Probá de nuevo.": "Couldn't get into that business. Try again.",
  "No se pudo cancelar la baja.": "The closing couldn't be canceled.",
  "Listo: cancelaste la baja. El negocio sigue como estaba.": "Done: you canceled the closing. The business stays as it was.",
  "No se pudo descargar. Recargá la página para probar de nuevo.": "It couldn't be downloaded. Reload the page to try again.",
  "Listo: tu mail quedó confirmado.": "Done: your email is confirmed.",
  "error:Ese enlace ya no sirve: venció o pediste uno más nuevo. Podés pedir otro desde Mi cuenta.": "error:That link no longer works: it expired or you requested a newer one. You can request another from My account.",
  "Tu mail quedó confirmado. Entrá con él.": "Your email is confirmed. Sign in with it.",

  // Palabras que llegan sueltas a un hueco ("{0} productos") o que el
  // extractor no ve (siglas): días, meses, el nombre del catálogo, IVA.
  "IVA": "VAT",
  "productos": "products",
  "producto": "product",
  "servicios": "services",
  "servicio": "service",
  "lunes": "Monday",
  "martes": "Tuesday",
  "jueves": "Thursday",
