  "noviembre": "November",
  "diciembre": "December",
  "tu@mail.com": "you@email.com",
  "No se pudo aceptar la invitación. Probá de nuevo desde el enlace del mail.": "The invitation couldn't be accepted. Try again from the email link.",
  "Ese enlace ya no sirve: venció o pediste uno más nuevo. Podés pedir otro desde Mi cuenta.": "That link no longer works: it expired or you requested a newer one. You can request another from My account.",
  "nombre@dominio.com": "name@domain.com",
  "El IVA de lo vendido (débito fiscal) sale de las facturas emitidas; el de lo comprado (crédito fiscal), de las compras con factura A. Las notas de crédito restan.": "VAT on sales (output tax) comes from the invoices issued; VAT on purchases (input tax), from purchases with an A invoice. Credit notes subtract.",
  "Escribí su nombre, DNI o número de socio. Si está al día, el ingreso queda anotado solo; si debe, te avisamos antes.": "Type their name, DNI or member number. If they're up to date, the check-in is recorded automatically; if they owe, we let you know first.",
  "Lo que se usa al vender sin venderse: la caja, la bolsa, el frasquito. Al vender, Nexo lo propone y se cambia en el momento si esa vez fue distinto; lo que quedó sale del stock y entra al costo de la venta.": "What's used when selling without being sold: the box, the bag, the small bottle. When selling, Nexo suggests it and you change it on the spot if that time was different; what's left comes out of stock and goes into the cost of the sale.",
  "Lo ves solo vos, como administrador de Nexo. De cada negocio, cuántas cosas cargó; nunca sus datos.": "Only you see this, as a Nexo administrator. For each business, how many things it entered; never its data.",
  "Elegí qué productos de Nexo publicar. Se crean en la tienda con su nombre, su descripción, sus variantes, su precio y su stock; las fotos y el diseño se cargan en Tienda Nube.": "Choose which Nexo products to publish. They're created in the store with their name, description, variants, price and stock; photos and design are set up in Tienda Nube.",
  "Elegí qué producto de Nexo es cada publicación. Si tienen el mismo SKU, ya viene elegido. Al vincular, la publicación toma el precio y el stock de Nexo; si el stock que vale es el de Mercado Libre, marcá “Traer su stock”.": "Choose which Nexo product each listing is. If they have the same SKU, it comes already chosen. When linking, the listing takes Nexo's price and stock; if the stock that counts is Mercado Libre's, check “Bring its stock”.",
  "Quién puede entrar a Nexo. Cada persona entra con su mail; para sumar a alguien, invitalo.": "Who can sign in to Nexo. Each person signs in with their email; to add someone, invite them.",
  "Le llega un mail con un enlace. Si todavía no usa Nexo, crea su cuenta desde ahí; si ya lo usa, acepta desde su cuenta.": "They get an email with a link. If they don't use Nexo yet, they create their account from there; if they already use it, they accept from their account.",
  "Para tener precios distintos de un mismo producto; por ejemplo, minorista y mayorista. La predeterminada es la que se usa si no elegís otra.": "To have different prices for the same product; for example, retail and wholesale. The default one is used if you don't choose another.",
  "Ordenan tus gastos. Los operativos restan del resultado del negocio; una inversión o un retiro no.": "They organize your expenses. Operating ones subtract from the business result; an investment or a withdrawal doesn't.",
  "¿Dar de baja este abono? No se arman más cuotas; las que ya hay siguen en la cuenta del cliente.": "Cancel this subscription? No more fees are created; the existing ones stay on the customer's account.",
  "Qué hay que hacer, cuándo y quién; al terminarlo, se cobra.": "What needs to be done, when and by whom; when it's finished, it's charged.",
  "--inicio: {0}; --largo: {1}; --carril: {2}; --carriles: {3}": null,
