  "Abre una segunda ventana para la gente, en el otro monitor de esta compu: cada socio tipea su DNI y entra solo. Si debe, te aparece acá arriba al instante.": "Opens a second window for people, on this computer's other monitor: each member types their ID and checks in on their own. If they owe, they show up here at the top instantly.",
