  // El QR de Mercado Pago en el mostrador (hist. §145)
  "Cobrar con QR de Mercado Pago": "Charge with a Mercado Pago QR",
  "Escaneá con la app de Mercado Pago o la cámara": "Scan with the Mercado Pago app or the camera",
