  "Notificaciones": "Notifications",
  "Avisos en el celular y la compu": "Alerts on your phone and computer",
  "Nexo te avisa en este aparato aunque no lo tengas abierto. Se prenden en cada celular o compu.": "Nexo alerts you on this device even when it isn't open. Turn them on in each phone or computer.",
  "En este aparato": "On this device",
