  "Entra una venta por Tienda Nube o Mercado Libre.": "A sale comes in from Tienda Nube or Mercado Libre.",
  "Te pagan con Mercado Pago.": "You get paid with Mercado Pago.",
  "Un producto llega al stock mínimo o se termina.": "A product reaches its minimum stock or runs out.",
  "Un socio que debe espera en la entrada.": "A member who owes is waiting at the entrance.",
  "Por ahora no hay avisos para tu rol en este negocio.": "For now there are no alerts for your role in this business.",
  "En el iPhone, primero instalá Nexo: abrila en Safari, tocá Compartir y después “Agregar a inicio”. Después abrila desde su ícono y prendelas acá.": "On the iPhone, install Nexo first: open it in Safari, tap Share and then “Add to Home Screen”. Then open it from its icon and turn them on here.",
  "Este navegador no permite notificaciones. Probá con Chrome, Edge, Firefox o Safari actualizados.": "This browser doesn't allow notifications. Try an up-to-date Chrome, Edge, Firefox or Safari.",
  "Las bloqueaste para Nexo. Para prenderlas, tocá el candado al lado de la dirección (o los permisos de la app) y permití las notificaciones.": "You blocked them for Nexo. To turn them on, tap the lock next to the address (or the app permissions) and allow notifications.",
